export function create(parent, doc, { onRun, onChange, label } = {}) {
  const runKey = { key: "Mod-Enter", preventDefault: true, run: () => { if (onRun) onRun(); return true; } };
  const view = new EditorView({
    parent,
    state: EditorState.create({
      doc,
      extensions: [
        lineNumbers(), highlightActiveLineGutter(), highlightActiveLine(), drawSelection(),
        history(), indentOnInput(), bracketMatching(), closeBrackets(),
        indentUnit.of("    "), EditorState.tabSize.of(4),
        python(), syntaxHighlighting(highlight), theme,
        keymap.of([runKey, ...closeBracketsKeymap, ...defaultKeymap, ...historyKeymap, indentWithTab]),
        EditorView.contentAttributes.of({ "aria-label": label || "Python code editor" }),
        EditorView.updateListener.of(u => { if (u.docChanged && onChange) onChange(); })
      ]
    })
  });
  return {
    view,
    getCode: () => view.state.doc.toString(),
    setCode: code => view.dispatch({ changes: { from: 0, to: view.state.doc.length, insert: code } }),
    focus: () => view.focus()
  };
}

// Lessons for the Python Playground, in order.
//
// Each lesson has:
//   id       URL hash, e.g. /python-playground/#loops (the cheat sheet links here)
//   title    shown in the lesson list
//   intro    short explanation (HTML)
//   task     what to do (HTML)
//   starter  starter code (Reset restores this)
//   check    Python run after the user's code. It can use:
//              ns        the user's variables, e.g. ns["age"]
//              output    everything the code printed, as one string
//              lines     printed lines, trimmed
//              code      the user's code as text
//              run_with  re-run the code with a variable changed, e.g. run_with(score=95)
//            Each failed `assert` shows its message to the user as the hint.

onmessage = async event => {
    const msg = event.data;
    if (msg.type !== "run") return;
    try {
        await ready;
    } catch (e) {
        return;
    }

    current = { id: msg.id, output: "", truncated: false, pending: [], pendingSize: 0, lastFlush: Date.now() };
    let result = { error: null };
    let check = null;
    try {
        result = JSON.parse(runUser(msg.code));
        if (msg.check) {
            check = result.error
                ? { passed: false, hint: "Your code raised an error. Fix it first (see the output panel), then check again." }
                : JSON.parse(runCheck(msg.check, current.output));
        }
    } catch (e) {
        result = { error: "Playground error: " + String((e && e.message) || e) };
    }
    flush();
    const id = current.id;
    current = null;
    postMessage({ type: "done", id, error: result.error, check });
};

const ready = (async () => {
    importScripts(PYODIDE_BASE + "pyodide.js");
    pyodide = await loadPyodide({ indexURL: PYODIDE_BASE });
    // Raw (unbuffered) handlers, so text printed with end="" isn't lost.
    const outDecoder = new TextDecoder();
    const errDecoder = new TextDecoder();
    pyodide.setStdout({ write: buf => { emit("stdout", outDecoder.decode(buf, { stream: true })); return buf.length; } });
    pyodide.setStderr({ write: buf => { emit("stderr", errDecoder.decode(buf, { stream: true })); return buf.length; } });
    pyodide.runPython(HARNESS);
    runUser = pyodide.globals.get("run_user");
    runCheck = pyodide.globals.get("run_check");
})();

def run_check(check, output):
    env = {
        "ns": _last["ns"],
        "code": _last["code"],
        "output": output,
        "lines": [l.rstrip() for l in output.strip().splitlines()],
        "run_with": run_with,
    }
    try:
        exec(check, env)
        return json.dumps({"passed": True, "hint": None})
    except AssertionError as e:
        return json.dumps({"passed": False, "hint": str(e) or "Not quite. Compare your output with the task."})
    except Exception as e:
        return json.dumps({"passed": False, "hint": f"Your code hit an error while being checked: {type(e).__name__}: {e}"})
